def public_legal_catalog() -> dict[str, Any]:
    supplier = _supplier()
    supplier_identity = (
        f"{supplier['name']}, {supplier['tax_id_label']} {supplier['tax_id']}, "
        f"com endereço em {supplier['address']} e contato {supplier['contact_email']}"
        if supplier["configured"] else "fornecedor do FROID (configuração jurídica pendente)"
    )
    documents: dict[str, Any] = {}
    for key, template in DOCUMENT_TEMPLATES.items():
        sections = [
            {
                "heading": heading,
                "body": body.format(
                    supplier_name=supplier["name"] or "fornecedor do FROID",
                    supplier_identity=supplier_identity,
                    # O canal de privacidade e PII de implantacao, como o resto
                    # da qualificacao: entra renderizado, nunca na fonte.
                    supplier_privacy_email=(
                        supplier["privacy_email"]
                        or "canal de privacidade do FROID (pendente)"
                    ),
                ),
            }
            for heading, body in template["sections"]
        ]
        rendered = {
            "key": key,
            "version": LEGAL_DOCUMENT_VERSION,
            "title": template["title"],
            "audiences": template["audiences"],
            "sections": sections,
        }
        canonical = json.dumps(rendered, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        rendered["sha256"] = hashlib.sha256(canonical.encode("utf-8")).hexdigest()
        documents[key] = rendered
    return {
        "version": LEGAL_DOCUMENT_VERSION,
        "supplier": supplier,
        "documents": documents,
    }


def required_document_keys(account_type: str) -> list[str]:
    # A empresa contratante do NR-1 nao assina contrato de profissional nem de
    # clinica: ela nao presta servico clinico e nao trata prontuario. Os dois
    # contratos do catalogo tem audiencia declarada ("professional" e
    # "organization"), e nenhuma delas e o empregador. Fazer o empregador
    # declarar aceite de um contrato profissional produziria registro juridico
    # falso — pior que nao coletar. Termos e privacidade valem para qualquer um
    # que use a plataforma, e esses continuam.
    #
    # O contrato empresarial de avaliacao NR-1 existe desde 22/08/2026 e diz, no
    # objeto, o que os outros dois nao podiam dizer: que a avaliacao olha para a
    # condicao de trabalho e nunca para a pessoa, e que a responsabilidade pelo
    # GRO continua sendo da empresa.
    #
    # OS TERMOS TAMBEM SE SEPARARAM, em 25/08/2026, e isso corrigiu uma
    # contradicao que ja estava no ar: o documento "terms" declara audiencias
    # professional, organization e patient — e NAO inclui nr1_company —, mas
    # esta funcao obrigava a empresa a aceita-lo. Ela assinava um documento que
    # dizia, no proprio corpo, nao ser para ela.
    #
    # Alem de contraditorio, era ruim para os dois lados. O texto unico falava
    # de gravacao de sessao, transcricao, prontuario e habilitacao profissional
    # para quem so vai abrir campanha; e falava de piso de coorte e inventario
    # de riscos para o psicologo autonomo. Aceite de clausula inaplicavel nao
    # protege ninguem: dilui o que e aplicavel e da ao advogado da outra parte
    # a primeira frase para dizer que o aceite foi generico.
    #
    # OS DOIS CONTRATOS DO PSIQUE VIRARAM UM, em 12/09/2026. Antes desta data o
    # profissional autonomo assinava `professional_contract` e a clinica
    # assinava `organization_contract` — dois textos que repetiam oito decimos
    # um do outro e ja divergiam entre si. Agora ambos assinam
    # `psique_contract`, cujas clausulas de pessoa juridica declaram o proprio
    # escopo na clausula 1.5, de modo que o autonomo nao aceita governanca de
    # perfis que a conta dele nao tem.
    #
    # A POLITICA TAMBEM SE SEPAROU, em 12/09/2026, pelo mesmo motivo dos termos:
    # o texto unico afirmava que o servico trata voz, imagem e transcricao — o
    # que e falso para quem so abre campanha — e calava sobre a protecao que a
    # empresa de fato recebe. Ver a lapide em DOCUMENT_TEMPLATES.
    if account_type == "nr1_company":
        return ["terms_nr1", "privacy_nr1", "nr1_company_contract"]
    return ["terms", "privacy", "psique_contract"]
